import org.apache.logging.log4j.*; import org.apache.logging.log4j.message.*;
public class Probe { static void row(String n,Logger a,Logger b,Logger root,MessageFactory f1,MessageFactory f2){System.out.println(n+"\tname="+a.getName()+"\tsame12="+(a==b)+"\tsameRoot="+(a==root)+"\tfactory1="+(a.getMessageFactory()==f1)+"\tfactory2="+(a.getMessageFactory()==f2)+"\tALL="+a.isEnabled(Level.ALL)+"\tTRACE="+a.isEnabled(Level.TRACE)+"\tDEBUG="+a.isEnabled(Level.DEBUG)+"\tINFO="+a.isEnabled(Level.INFO)+"\tWARN="+a.isEnabled(Level.WARN)+"\tERROR="+a.isEnabled(Level.ERROR)+"\tFATAL="+a.isEnabled(Level.FATAL)+"\tOFF="+a.isEnabled(Level.OFF));} public static void main(String[]x){MessageFactory f1=new ParameterizedMessageFactory(), f2=new ParameterizedMessageFactory(), f3=new StringFormatterMessageFactory(); Logger root=LogManager.getLogger("x"); row("f1",LogManager.getLogger("x",f1),LogManager.getLogger("x",f1),root,f1,f2); row("f2",LogManager.getLogger("x",f2),LogManager.getLogger("x",f2),root,f1,f2); row("f3",LogManager.getLogger("x",f3),LogManager.getLogger("x",f3),root,f1,f3);}}
